from pathlib import Path
import runpy
structures=runpy.run_path(str(Path(__file__).with_name("schema-structures.py")))
from xml.sax.saxutils import escape
roots={
'evaluation':'deck bots batch rules content starting_orders limits output',
'manifest':'run_id created_at application_revision runtime_sha256 runtime engine content rules deck bots configuration identity_sha256',
'progress':'run_id status updated_at last_finalized_match active_match active_game next_unstarted_match completed_game_ids incomplete_match_ids bug_ids',
'match':'run_id match_id status games sideboarding result perspective_reports',
'player-report':'run_id match_id perspective bot_artifact_sha256 games sideboarding',
'summary':'run_id status counts results card_decisions effects combat resources sideboarding decision_behavior performance reliability materials aggregation_rules',
'evaluation-report':'run_id manifest_path summary_path configuration_description results decision_investigations sideboarding performance_and_reliability comparison_references limitations',
'comparison':'comparison_id baseline_run candidate_run baseline_manifest_sha256 candidate_manifest_sha256 comparison_mode comparability metrics decision_changes sideboarding_changes new_bug_ids recurring_failure_signatures previously_observed_bugs_not_seen limitations performance_changes reliability_changes',
'comparison-report':'comparison_id comparison_path compared_runs comparability result_changes decision_changes sideboarding_changes performance_changes reliability_changes recommendations',
'bug-ticket':'bug_id title status failure_signature occurrence_count expected_behavior observed_behavior affected_executions environment reproduction attachments diagnosis acceptance_criteria',
'diagnostics':'bug_id classification failure_signature occurrences',
'starting-orders':'matches'
}
strings='node_flags measurement_boundary runtime_sha256 starting_player banlist snapshot configuration_sha256 run_id created_at application_revision node os cpu version sha256 snapshot_id profile banlist_sha256 module artifact_sha256 config_sha256 identity_sha256 status updated_at game_id match_id stage starter winner evidence_sha256 bug_id failure_category skip_reason outcome a b perspective bot_artifact_sha256 rules_profile card_code instance_id phase kind decision_id actor id action card_instance_id code explanation type event caused_by_decision_id from_section to_section reason_code resulting_configuration_sha256 engine_reason manifest_path summary_path configuration_description metric_reference observation hypothesis path suggested_next_step limitation comparison_id baseline_run candidate_run baseline_manifest_sha256 candidate_manifest_sha256 comparison_mode changed_bot name method comparison_path assessment next_step title failure_signature expected_behavior observed_behavior occurrence_id player partial_evidence_sha256 identity_notes reproducibility command_or_configuration next_investigation_step criterion classification message stack bot_debug_state category manifest unavailable_reason source dependency_path artifact_source input_sha256 signature exact_input_sha256 warm_target_status aggregation_rule mode fixture_path execution directory sum_mode reason captured_at reference_game_id reference_decision_id section location position owner controller turn_player snapshot_id preset_id label source_instance_id source_card description source_identity_visible target action_name signature_hash'.split()
integers='baseline_sample_size candidate_sample_size overlay_sequence released_by_host_termination amount size memory_bytes matches last_finalized_match active_match active_game next_unstarted_match number a_wins b_wins draws copies turn opponent_hand_count opponent_deck_count sequence minimum maximum slot turns numerator denominator matches_requested matches_completed matches_incomplete games_scheduled games_completed games_failed games_skipped game_wins game_losses game_draws match_wins match_losses match_ties event_count player_games_with_action wins_in_those_games legal_opportunities opportunities_declined peak_resident_memory_bytes occurrence_count limit_ms last_progress_sequence max_turns_per_game max_decisions_per_game game_wall_time_ms decision_wall_time_ms sideboarding_wall_time_ms sample_size handles_created handles_destroyed rss_bytes required_total allocation_maximum hand_count deck_count extra_deck_count revision chain_index count index life_points maximum_events_per_game completed_games_from_incomplete_matches start_memory_bytes end_memory_bytes host_restarts reference_count bridge_bytes'.split()
numbers='end_to_end_ms host_time_ms host_setup_ms projection_ms ipc_ms evidence_hash_ms serialization_ms schema_validation_ms filesystem_ms delta_count value duration_ms startup_ms completed_games_per_second p50 p95 p99 maximum engine_time_ms bot_time_ms bridge_time_ms report_write_time_ms delta_percentage_points confidence_level lower upper warm_game_p95_ms elapsed_ms standard_error'.split()
booleans='timing_complete direct draw ordered cancelable preserve_section_sizes preserve_total_multiset same_input_deck same_rules_and_banlist same_engine_and_content same_opponent_artifact_and_config same_starting_order_cases selected before_initial face_up identity_visible passed confounded'.split()
objects='costs game_samples materials aggregation_rules successful_resolutions fixture match_uncertainty cards place deck bots batch rules content starting_orders limits output runtime engine configuration main extra side card config completed_game_ids incomplete_match_ids bug_ids games game sideboarding result perspective_reports initial own_configuration own_starting_order own_opening_hand public_state timeline entry prompt constraints choices choice selected_choice_ids reason factors factor changes change from to position observed_game_ids legal_constraints exchanges exchange resulting_configuration counts results game_win_rate match_win_rate match_score_distribution by_stage pre_side post_side card_decisions card_decision conditional_win_rate effects combat resources decision_behavior performance game_duration_ms decision_duration_ms reliability failures_by_category bugs metric_references observations decision_investigations investigation evidence performance_and_reliability bug_references comparison_references limitations comparability notes note metrics metric baseline candidate uncertainty interval_percentage_points decision_changes sideboarding_changes new_bug_ids recurring_failure_signatures previously_observed_bugs_not_seen compared_runs result_changes performance_changes reliability_changes new_bug_references recurring_failure_references recommendations recommendation affected_executions execution environment reproduction starting_conditions_reference last_action pending_prompt_reference attempted_response_reference observed_random_events_reference missing_evidence attachments reference diagnosis known_facts hypotheses acceptance_criteria occurrences occurrence failure identity last_checkpoint pending_prompt attempted_response recent_engine_events private_engine_state unavailable_evidence details item to_record overlay_materials counters chain targets mandatory_contributions contribution parameter dependencies dependency acceptance_target performance_target cleanup memory_samples sample actor_mapping aggregate_rule records record matches'.split()
# A scalar/structured name used in more than one context is mixed, with typed descendants.
scalar={k:'xs:string' for k in strings};scalar.update({k:'xs:nonNegativeInteger' for k in integers});scalar.update({k:'xs:double' for k in numbers});scalar.update({k:'xs:boolean' for k in booleans});scalar['delta_count']='xs:integer'
allnames=set(objects)|set(scalar)|{k for v in roots.values() for k in v.split()}|{'opponent_deck','configuration_sha256','last_action','is_hidden','choice_id','card','sort','data','flags','chain_size','monster_count','spell_trap_count','graveyard_count','banished_count','display_order','is_public','is_hidden','alternative_contribution','a_configuration_sha256','b_configuration_sha256'}
conflicts={'card','a','b','reason','life_points','from','to','position','source','failure','observation','contribution','value','target','maximum','identity_visible','player','owner','controller','source_identity_visible'}
for root,required in roots.items():
 lines=['<?xml version="1.0" encoding="UTF-8"?>','<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema">','<xs:complexType name="record" mixed="true"><xs:choice minOccurs="0" maxOccurs="unbounded">']
 for name in sorted(allnames):
  ty='fixtureRecord' if name=='fixture' else 'bot-config' if name=='config' else 'statusType' if name=='status' else 'record' if name in objects or name in conflicts or name not in scalar else scalar[name]
  lines.append(f'<xs:element name="{name}" type="{ty}" nillable="true"/>')
 lines+=['</xs:choice>'+''.join(f'<xs:attribute name="{name}" type="xs:string" use="optional"/>' for name in ['path','game_id','decision_id','classification','manifest_path'])+'</xs:complexType>', '<xs:complexType name="bot-config"><xs:sequence><xs:any minOccurs="0" maxOccurs="unbounded" processContents="skip"/></xs:sequence></xs:complexType>', '<xs:simpleType name="statusType"><xs:restriction base="xs:string">'+''.join('<xs:enumeration value="'+v+'"/>' for v in ['running','completed','interrupted','failed','incomplete','skipped','needs_diagnosis'])+'</xs:restriction></xs:simpleType>',f'<xs:element name="{root}"><xs:complexType><xs:all>']
 for name in required.split():
  ty=structures['OVERRIDES'].get(root,{}).get(name, 'record' if name in objects or name not in scalar else scalar[name])
  lines.append(f'<xs:element name="{name}" type="{ty}" nillable="{str(root=="progress" and name in ["active_match","active_game"]).lower()}"/>')
 if root in ['evaluation','manifest']:lines.append('<xs:element name="opponent_deck" type="'+('evalDeck' if root=='evaluation' else 'record')+'" minOccurs="0"/>')
 if root=='evaluation':lines.append('<xs:element name="performance_target" type="evalTarget" minOccurs="0"/>')
 lines+=['</xs:all><xs:attribute name="schema_version" type="xs:positiveInteger" use="required" fixed="1"/></xs:complexType></xs:element>','</xs:schema>']
 lines[-1:-1]=structures['named_types']()
 Path(f'schemas/bot-evaluation/v1/{root}.xsd').write_text('\n'.join(lines)+'\n')

# The standalone timeline uses exactly the same named type as player-report.
source=Path('schemas/bot-evaluation/v1/player-report.xsd').read_text()
start=source.index('<xs:element name="player-report"><xs:complexType><xs:all>')
end=source.index('</xs:complexType></xs:element>',start)+len('</xs:complexType></xs:element>')
source=source[:start]+'<xs:element name="timeline-fragment"><xs:complexType><xs:complexContent><xs:extension base="timelineRecord"><xs:attribute name="schema_version" type="xs:positiveInteger" use="required" fixed="1"/></xs:extension></xs:complexContent></xs:complexType></xs:element>'+source[end:]
Path('schemas/bot-evaluation/v1/timeline-fragment.xsd').write_text(source)
